100:         output->GetDesc(&desc);
101:         _pOutputDeviceList.append(QString::fromWCharArray(desc.DeviceName));
102:     }
103:     if (outputID >= 0 && outputID < dxgiOutputVector.count())
104:     {
105:         dxgiOutput = dxgiOutputVector.at(outputID);
