171: void ElaDxgi::onGrabScreen()
172: {
173:     if (!_duplication || !_device || !_context)
174:     {
175:         setIsGrabStoped(true);
176:         return;
177:     }
178:     _pIsGrabStoped = false;
179:     while (_pIsGrabActive)
180:     {
181:         IDXGIResource* desktopRes = nullptr;
182:         DXGI_OUTDUPL_FRAME_INFO frameInfo;
183:         while (true)
184:         {
185:             if (!_pIsGrabActive)
186:             {
187:                 setIsGrabStoped(true);
188:                 return;
189:             }
190:             _grabTimer.start();
191:             _duplication->ReleaseFrame();
192:             HRESULT hr = _duplication->AcquireNextFrame(_pTimeoutMsValue, &frameInfo, &desktopRes);
193:             if (FAILED(hr))
194:             {
195:                 if (hr != DXGI_ERROR_WAIT_TIMEOUT)
196:                 {
197:                     if (desktopRes)
198:                     {
199:                         desktopRes->Release();
200:                         desktopRes = nullptr;
201:                     }
202:                     while (true)
203:                     {
204:                         if (!_duplication || !_device || !_context)
205:                         {
206:                             setIsGrabStoped(true);
207:                             return;
208:                         }
209:                         if (initialize(_pDxDeviceID, _pOutputDeviceID))
210:                         {
211:                             break;
212:                         }
213:                     }
214:                 }
215:                 continue;
216:             }
217:             if (frameInfo.LastPresentTime.QuadPart)
218:             {
219:                 break;
220:             }
221:         }
222:         D3D11_TEXTURE2D_DESC desc;
223:         ID3D11Texture2D* textrueRes = nullptr;
224:         HRESULT hr = desktopRes->QueryInterface(__uuidof(ID3D11Texture2D), reinterpret_cast<void**>(&textrueRes));
225:         desktopRes->Release();
226:         if (FAILED(hr))
227:         {
228:             qDebug() << "Failed to ID3D11Texture2D result =" << QString::number(uint(hr), 16);
229:             continue;
230:         }
231:         textrueRes->GetDesc(&desc);
232:         D3D11_TEXTURE2D_DESC texDesc;
233:         ZeroMemory(&texDesc, sizeof(texDesc));
234:         texDesc.Width = desc.Width;
235:         texDesc.Height = desc.Height;
236:         texDesc.MipLevels = 1;
237:         texDesc.ArraySize = 1;
238:         texDesc.SampleDesc.Count = 1;
239:         texDesc.SampleDesc.Quality = 0;
240:         texDesc.Usage = D3D11_USAGE_STAGING;
241:         texDesc.Format = desc.Format;
242:         texDesc.BindFlags = 0;
243:         texDesc.CPUAccessFlags = D3D11_CPU_ACCESS_READ;
244:         texDesc.MiscFlags = 0;
245:         _device->CreateTexture2D(&texDesc, nullptr, &_texture);
246:         _context->CopyResource(_texture, textrueRes);
247:         IDXGISurface1* surface = nullptr;
248:         hr = _texture->QueryInterface(__uuidof(IDXGISurface1), reinterpret_cast<void**>(&surface));
249:         if (FAILED(hr))
250:         {
251:             qDebug() << "Failed to QueryInterface IDXGISurface1 ErrorCode ="
252:                      << QString::number(uint(hr), 16);
253:             continue;
254:         }
255:         DXGI_MAPPED_RECT map;
256:         surface->Map(&map, DXGI_MAP_READ);
257:         _imageBits = static_cast<uchar*>(map.pBits);
258:         _descWidth = desc.Width;
259:         _descHeight = desc.Height;
260:         surface->Unmap();
261:         surface->Release();
262:         _texture->Release();
263:         QImage grabImage(_imageBits, _descWidth, _descHeight, QImage::Format_ARGB32);
264:         if (_pIsGrabCenter)
265:         {
266:             Q_EMIT grabScreenOver(std::move(grabImage.copy(QRect((_descWidth - _pGrabArea.width()) / 2, (_descHeight - _pGrabArea.height()) / 2, _pGrabArea.width(), _pGrabArea.height()))));
267:         }
268:         else
269:         {
270:             Q_EMIT grabScreenOver(std::move(grabImage.copy(_pGrabArea)));
271:         }
272:         if (_lastGrabTime == 0)
273:         {
274:             _lastGrabTime = _grabTimer.elapsed(); // 毫秒
275:         }
276:         else
277:         {
278:             _lastGrabTime = (_grabTimer.elapsed() + _lastGrabTime) / 2;
279:         }
280:         _cpuSleepTime = (1000 - _lastGrabTime * _pGrabFrameRate) / _pGrabFrameRate;
281:         cpuSleep(_cpuSleepTime * 1000);
282:         // qDebug() << _cpuSleepTime << _lastGrabTime;
283:     }
284:     setIsGrabStoped(true);
285: }
